import{_ as t,c as a,o as n,ag as o}from"./chunks/framework.CB_NIqHd.js";const p=JSON.parse('{"title":"What is a style guide?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Clean_code_and_Code_Quality/What_is_a_style_guide.md","filePath":"senior_growth/Clean_code_and_Code_Quality/What_is_a_style_guide.md"}'),r={name:"senior_growth/Clean_code_and_Code_Quality/What_is_a_style_guide.md"};function i(s,e,l,d,c,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-a-style-guide" tabindex="-1">What is a style guide? <a class="header-anchor" href="#what-is-a-style-guide" aria-label="Permalink to “What is a style guide?”">​</a></h1><h1 id="🎨-style-guide-in-software-development" tabindex="-1">🎨 Style Guide in Software Development <a class="header-anchor" href="#🎨-style-guide-in-software-development" aria-label="Permalink to “🎨 Style Guide in Software Development”">​</a></h1><p>A <strong>style guide</strong> is a <strong>document or set of rules</strong> that defines how code should be <strong>written, formatted, and structured</strong> in a project or organization. It ensures <strong>consistency and readability</strong> across the codebase, making it easier for teams to maintain and scale software.</p><hr><h2 id="_1️⃣-purpose-of-a-style-guide" tabindex="-1">1️⃣ Purpose of a Style Guide <a class="header-anchor" href="#_1️⃣-purpose-of-a-style-guide" aria-label="Permalink to “1️⃣ Purpose of a Style Guide”">​</a></h2><ul><li><strong>Consistency:</strong> All developers follow the same conventions, reducing cognitive load.</li><li><strong>Readability:</strong> Easier for team members to understand code quickly.</li><li><strong>Maintainability:</strong> Simplifies code reviews, debugging, and refactoring.</li><li><strong>Collaboration:</strong> Reduces conflicts and misunderstandings in team environments.</li><li><strong>Tool Integration:</strong> Works with linters, formatters, and CI/CD pipelines for automated enforcement.</li></ul><hr><h2 id="_2️⃣-common-components-of-a-style-guide" tabindex="-1">2️⃣ Common Components of a Style Guide <a class="header-anchor" href="#_2️⃣-common-components-of-a-style-guide" aria-label="Permalink to “2️⃣ Common Components of a Style Guide”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Formatting</strong></td><td>Indentation (2 vs 4 spaces), line length, spaces vs tabs, semicolons</td></tr><tr><td><strong>Naming conventions</strong></td><td>camelCase for variables, PascalCase for components, UPPER_CASE for constants</td></tr><tr><td><strong>File/folder structure</strong></td><td>Grouping by feature/module, naming conventions for files</td></tr><tr><td><strong>Code patterns</strong></td><td>Preferred ways to write loops, functions, or hooks</td></tr><tr><td><strong>Comments/documentation</strong></td><td>When and how to comment code; docstring standards</td></tr><tr><td><strong>Best practices</strong></td><td>Immutability, error handling, side-effect management, accessibility standards in UI</td></tr><tr><td><strong>Testing</strong></td><td>Where and how tests should be written (unit, integration, E2E)</td></tr></tbody></table><hr><h2 id="_3️⃣-examples-of-style-guides" tabindex="-1">3️⃣ Examples of Style Guides <a class="header-anchor" href="#_3️⃣-examples-of-style-guides" aria-label="Permalink to “3️⃣ Examples of Style Guides”">​</a></h2><ul><li><strong>JavaScript / TypeScript:</strong><ul><li>Airbnb JavaScript Style Guide</li><li>Google JavaScript Style Guide</li><li>StandardJS</li></ul></li><li><strong>CSS / SCSS / Styled Components:</strong><ul><li>CSS Guidelines by Harry Roberts</li><li>Stylelint recommended rules</li></ul></li><li><strong>React / Frontend:</strong><ul><li>React/JSX rules for hooks, component naming, props handling</li></ul></li></ul><hr><h2 id="_4️⃣-enforcement" tabindex="-1">4️⃣ Enforcement <a class="header-anchor" href="#_4️⃣-enforcement" aria-label="Permalink to “4️⃣ Enforcement”">​</a></h2><ul><li><strong>Linters:</strong> ESLint with typescript-eslint for TypeScript, and Stylelint for CSS. TSLint was deprecated in2019 and belongs to migration history.</li><li><strong>Formatters:</strong> Prettier ensures consistent formatting.</li><li><strong>Pre-commit hooks:</strong> Husky + lint-staged can provide local feedback; hooks can be bypassed, so required gates also run in CI.</li><li><strong>CI/CD pipelines:</strong> Ensure all PRs comply with style guide rules before merging.</li></ul><hr><h2 id="✅-key-takeaways" tabindex="-1">✅ Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “✅ Key Takeaways”">​</a></h2><ul><li><strong>Style guide = team-agreed conventions for writing code</strong></li><li>Ensures <strong>consistent, readable, maintainable code</strong> across projects</li><li>Works hand-in-hand with <strong>linters, formatters, and automated pipelines</strong></li><li>Makes <strong>code reviews faster and more effective</strong> because reviewers focus on logic, not style</li></ul><blockquote><p>💡 Senior Tip:<br> A style guide is not just about aesthetics—it’s <strong>a contract that communicates code intent and quality</strong> across the team.</p></blockquote><h2 id="team-policy-exceptions-and-rollout" tabindex="-1">Team policy, exceptions and rollout <a class="header-anchor" href="#team-policy-exceptions-and-rollout" aria-label="Permalink to “Team policy, exceptions and rollout”">​</a></h2><p>Separate formatting (Prettier), mechanically checkable correctness rules (ESLint/typescript-eslint), compiler checks (tsc) and human design guidance. A formatter cannot prove safe asynchronous ownership; a typechecker cannot prove the correct business calculation. Prefer one formatter owner rather than conflicting lint formatting rules. Refer to the <a href="./What_practices%2C_approaches_do_you_know_which_helps_to_improve_code_quality_(style_guides%2C_coding_principles).html#worked-static-gates-and-a-small-domain-refactor">worked typed quality gates and refactor</a>.</p><p>Record rule purpose, scope and an example of both acceptable and rejected code. Example policy: await or explicitly handle rejecting promises at service boundaries; name domain concepts consistently; require public API changes to include consumer/migration evidence. New rules should be piloted on representative code and introduced in a focused cleanup or changed-code rollout with a bounded legacy backlog. Do not combine a whole-repo reformat with an unrelated bug fix.</p><p>An exception needs a narrow suppression, rule name, concrete reason, owner and follow-up condition. Avoid file-wide disable comments for one line. A warning budget can be part of a migration, but required correctness rules must fail the build once adopted. Complexity/coverage numbers identify code to investigate; the team should justify thresholds from risk and maintainability rather than treat an arbitrary score as proof of quality. Revisit expensive/noisy rules when evidence shows poor signal; disabling a rule is a reviewed policy change.</p><p><strong>Practice acceptance:</strong> write a one-page team guide with3–5 high-value rules, wire compiler/lint/format checks independently in a separate project, demonstrate one valid exception and one rejected broad suppression, and make CI fail when a hook is bypassed. Retain diagnostics and decision reasons. Learner implementation remains required.</p><p>References checked2026-10-21: <a href="https://palantir.github.io/tslint/" target="_blank" rel="noreferrer">TSLint deprecation</a>, <a href="https://typescript-eslint.io/getting-started/typed-linting/" target="_blank" rel="noreferrer">typescript-eslint typed linting</a>, <a href="https://eslint.org/docs/latest/use/configure/configuration-files" target="_blank" rel="noreferrer">ESLint configuration</a>.</p>',25)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
